{"metadata":{"kernelspec":{"name":"ir","display_name":"R","language":"R"},"language_info":{"name":"R","codemirror_mode":"r","pygments_lexer":"r","mimetype":"text/x-r-source","file_extension":".r","version":"4.4.0"},"kaggle":{"accelerator":"none","dataSources":[],"dockerImageVersionId":31330,"isInternetEnabled":true,"language":"r","sourceType":"notebook","isGpuEnabled":false}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"code","source":"# This R environment comes with many helpful analytics packages installed\n# It is defined by the kaggle/rstats Docker image: https://github.com/kaggle/docker-rstats\n# For example, here's a helpful package to load\n\nlibrary(tidyverse) # metapackage of all tidyverse packages\n\n# Input data files are available in the read-only \"../input/\" directory\n# For example, running this (by clicking run or pressing Shift+Enter) will list all files under the input directory\n\nlist.files(path = \"../input\")\n\n# You can write up to 20GB to the current directory (/kaggle/working/) that gets preserved as output when you create a version using \"Save & Run All\" \n# You can also write temporary files to /kaggle/temp/, but they won't be saved outside of the current session","metadata":{"_uuid":"051d70d956493feee0c6d64651c6a088724dca2a","_execution_state":"idle","trusted":true},"outputs":[],"execution_count":null},{"cell_type":"code","source":"\n# ============================================================\n# MACD分析 - 複数インデックス対応版（ハル移動平均線版）\n# WEBからデータを取得し、インデックスを選択可能\n#\n# 変更点：smooth.spline → ハル移動平均線（HMA）\n#   HMA(n) = WMA(2×WMA(n/2) − WMA(n), √n)\n#   スプラインより応答が速く、ラグが小さい平滑化手法\n# ============================================================\n\n# ── 1. パッケージ・設定 ────────────────────────────────────\n\nlibrary(TTR)\nlibrary(quantmod)\nlibrary(kableExtra)\n\nSys.setenv(LANGUAGE = \"ja\", TZ = \"Asia/Tokyo\")\n\n# ── 2. インデックス選択メニュー ────────────────────────────\n\ncat(\"\\n========== インデックス選択 ==========\\n\")\ncat(\"1. 日経平均 (^N225)\\n\")\ncat(\"2. ダウ平均 (^DJI)\\n\")\ncat(\"3. S&P 500 (^GSPC)\\n\")\ncat(\"4. ナスダック (^IXIC)\\n\")\ncat(\"=====================================\\n\")\n\nselection <- as.integer(readline(\"選択してください (1-4): \"))\n\n\n# ------------------------------------------------\n","metadata":{"trusted":true},"outputs":[],"execution_count":null},{"cell_type":"code","source":"\nindex_info <- list(\n  list(number = 1, name = \"日経平均\",   symbol = \"^N225\",  label = \"日経平均\"),\n  list(number = 2, name = \"ダウ平均\",   symbol = \"^DJI\",   label = \"ダウ平均\"),\n  list(number = 3, name = \"S&P 500\",    symbol = \"^GSPC\",  label = \"S&P 500\"),\n  list(number = 4, name = \"ナスダック\", symbol = \"^IXIC\",  label = \"ナスダック\")\n)\n\nif (is.na(selection) || selection < 1 || selection > 4) {\n  cat(\"無効な選択です。デフォルトで日経平均を使用します。\\n\")\n  selection <- 1\n}\n\nselected   <- index_info[[selection]]\nsymbol     <- selected$symbol\nindex_name <- selected$label\n\ncat(paste0(\"\\n選択されたインデックス: \", index_name, \" (\", symbol, \")\\n\"))\ncat(\"データを取得中...\\n\\n\")\n","metadata":{"trusted":true},"outputs":[],"execution_count":null},{"cell_type":"code","source":"\n\n# ── 3. データ取得 ──────────────────────────────────────────\n\ntryCatch({\n  suppressWarnings({\n    data_xts <- getSymbols(symbol, src = \"yahoo\",\n                           from = Sys.Date() - 730, to = Sys.Date(),\n                           periodicity = \"daily\", auto.assign = FALSE)\n  })\n  df <- data.frame(\n    date  = as.Date(index(data_xts)),\n    close = as.numeric(Cl(data_xts))\n  )\n  df <- na.omit(df)\n  rownames(df) <- NULL\n  if (nrow(df) == 0) stop(\"有効なデータが取得できませんでした\")\n  cat(paste0(\"データ取得完了: \", nrow(df), \"行のデータを読み込みました。\\n\"))\n  cat(paste0(\"期間: \", min(df$date), \" ～ \", max(df$date), \"\\n\\n\"))\n}, error = function(e) {\n  cat(\"エラー: データの取得に失敗しました。\\n\")\n  cat(\"エラーメッセージ: \", conditionMessage(e), \"\\n\")\n  stop(e)\n})\n","metadata":{"trusted":true},"outputs":[],"execution_count":null},{"cell_type":"code","source":"\n# ── 4. MACD計算 ───────────────────────────────────────────\n# MACDは短期EMA（12日）と長期EMA（26日）の差。\n# シグナルはMACDの9日EMA。ヒストグラム = MACD − シグナル。\n\nmacd      <- MACD(df$close, nFast = 12, nSlow = 26, nSig = 9)\ndf$macd   <- macd[, 1]\ndf$signal <- macd[, 2]\ndf$hist   <- df$macd - df$signal\ndf        <- na.omit(df)\n\n\n# ── 5. ハル移動平均線（HMA）定義・計算 ────────────────────\n# HMA(n) = WMA(2×WMA(n/2) − WMA(n), √n)\n# - WMA(n/2)：短期の動きを2倍に増幅し、ラグを前倒し補正\n# - 最後に√n期間のWMAで平滑化\n# スプライン曲線との比較：\n#   smooth.spline → 事後的な全期間フィット（将来データを参照）\n#   HMA           → 過去データのみを使ったリアルタイム指標\n\nHMA <- function(price, n = 20) {\n  wma_half <- WMA(price, n = max(2L, floor(n / 2)))\n  wma_full <- WMA(price, n = n)\n  raw      <- 2 * wma_half - wma_full\n  WMA(raw, n = max(2L, floor(sqrt(n))))\n}\n\nHMA_N         <- 20                           # HMAの期間（変更可能）\nhma_all       <- HMA(df$hist, n = HMA_N)     # 全期間HMA\nhma_slope_all <- c(NA, diff(hma_all))         # HMAの傾き（変化の速度）\n\n# ── 6. ヘルパー関数 ───────────────────────────────────────\n\nadd_month_lines <- function(dates, jan_col = \"green\", other_col = \"lightgray\") {\n  ms <- unique(as.Date(format(dates, \"%Y-%m-01\")))\n  m  <- as.integer(format(ms, \"%m\"))\n  abline(v = as.numeric(ms[m != 1]), col = other_col, lty = 1)\n  abline(v = as.numeric(ms[m == 1]), col = jan_col,   lty = 1, lwd = 1.5)\n  ms15 <- as.Date(format(ms, \"%Y-%m-15\"))\n  abline(v = as.numeric(ms15), col = \"lightgray\", lty = 3)\n  text(x = as.numeric(ms), y = par(\"usr\")[3],\n       labels = m, col = ifelse(m == 1, jan_col, \"black\"),\n       xpd = TRUE, cex = 0.7, adj = c(0.5, 1.5))\n}\n\n# HMAの差分（有効値のみ）を使ってピーク・谷を検出するヘルパー\ndetect_peaks_valleys <- function(hma_vec) {\n  valid      <- which(!is.na(hma_vec))\n  hma_vals   <- hma_vec[valid]\n  hma_d      <- diff(hma_vals)\n  dsd        <- diff(sign(hma_d))\n  sc         <- which(dsd != 0)\n  peak_raw   <- sc[dsd[sc] < 0] + 1   # 傾き 正→負：山\n  valley_raw <- sc[dsd[sc] > 0] + 1   # 傾き 負→正：谷\n  list(\n    peak_idx   = valid[peak_raw],\n    valley_idx = valid[valley_raw]\n  )\n}\n\n","metadata":{"trusted":true},"outputs":[],"execution_count":null},{"cell_type":"code","source":"\n# ── 7. グラフ（全期間） ────────────────────────────────────\n\n\n# 終値\nplot(df$date, df$close, type = \"l\",\n     main = paste0(index_name, \" - 終値\"),\n     xlab = \"日付\", ylab = \"終値\")\nadd_month_lines(df$date)\n\n# MACDヒストグラム＋HMA\nplot(df$date, df$hist, type = \"l\",\n     main = paste0(index_name, \" - MACDヒストグラム + HMA(\", HMA_N, \")\"),\n     xlab = \"日付\", ylab = \"MACD Histogram\")\nlines(df$date, hma_all, col = \"red\", lwd = 2)\nadd_month_lines(df$date)\nabline(h = 0, col = \"darkgoldenrod\", lty = 1)\nlegend(\"topright\",\n       legend = c(\"Histogram\", paste0(\"HMA(\", HMA_N, \")\")),\n       col = c(\"black\", \"red\"), lty = 1, cex = 0.7, bty = \"n\")\n\n# HMAの傾き（変化の速度　＝　スプライン版の1階微分に相当）\nplot(df$date, hma_slope_all, type = \"l\",\n     main = paste0(index_name, \" - HMA傾き（変化の速度）\"),\n     xlab = \"日付\", ylab = \"HMA slope\")\nadd_month_lines(df$date)\nabline(h = 0, col = \"gray\", lty = 2)\n\n","metadata":{"trusted":true},"outputs":[],"execution_count":null},{"cell_type":"code","source":"\n# ── 8. 直近N日の分析 ──────────────────────────────────────\n# 期間を変えたい場合はここだけ変更する\n\nN <- 100\n\ndf_recent     <- tail(df, N)\nhma_recent    <- HMA(df_recent$hist, n = HMA_N)\nhma_slope_rec <- c(NA, diff(hma_recent))\n\n# 終値（直近N日）\nplot(df_recent$date, df_recent$close, type = \"l\",\n     main = paste0(index_name, \" - 終値（直近 \", N, \" 日）\"),\n     xlab = \"日付\", ylab = \"終値\")\nadd_month_lines(df_recent$date)\n\n# MACDヒストグラム＋HMA（直近N日）\nplot(df_recent$date, df_recent$hist, type = \"l\",\n     main = paste0(index_name, \" - MACDヒストグラム + HMA(\", HMA_N, \")（直近 \", N, \" 日）\"),\n     xlab = \"日付\", ylab = \"MACD Histogram\")\nlines(df_recent$date, hma_recent, col = \"red\", lwd = 2)\nabline(h = 0, col = \"darkgoldenrod\", lty = 2)\nadd_month_lines(df_recent$date)\nlegend(\"topleft\",\n       legend = c(\"Histogram\", paste0(\"HMA(\", HMA_N, \")\")),\n       col = c(\"black\", \"red\"), lty = 1, cex = 0.7)\n\n\n\n# ------------------------------------------------------------\n","metadata":{"trusted":true},"outputs":[],"execution_count":null},{"cell_type":"code","source":"\n# HMAの傾き（直近N日）\nplot(df_recent$date, hma_slope_rec, type = \"l\",\n     main = paste0(index_name, \" - HMA傾き（直近 \", N, \" 日）\"),\n     xlab = \"日付\", ylab = \"HMA slope\")\nadd_month_lines(df_recent$date)\nabline(h = 0, col = \"gray\", lty = 2)\n\n\n# ── 9. 頂点・谷底マーカー（直近N日）──────────────────────\n# ★グラフのサイズ指定（幅15インチ、高さ7インチに拡大）\noptions(repr.plot.width = 15, repr.plot.height = 7)\n\npv <- detect_peaks_valleys(hma_recent)\npeak_idx <- pv$peak_idx\nvalley_idx <- pv$valley_idx\n\n# ヒストグラム（実値）の山・谷\nhist_sign_changes <- which(diff(sign(diff(df_recent$hist))) != 0 ) + 1\nhist_peak_idx <- hist_sign_changes[diff(df_recent$hist)[hist_sign_changes - 1 ] > 0 ]\nhist_valley_idx <- hist_sign_changes[diff(df_recent$hist)[hist_sign_changes - 1 ] < 0 ]\n\n# プロット開始\nplot(df_recent$date, df_recent$hist, type = \"l\", \n     main = paste0(index_name, \" - MACDヒストグラム 頂点・谷底（直近 \", N, \" 日）\"), \n     xlab = \"日付\", ylab = \"MACD Histogram\")\nlines(df_recent$date, hma_recent, col = \"red\", lwd = 2)\n\n# HMAの山・谷マーカー（点プロット）\npoints(df_recent$date[peak_idx],   hma_recent[peak_idx], pch = 25, col = \"blue\", bg = \"blue\", cex = 1.2) # 山 ▼\npoints(df_recent$date[valley_idx], hma_recent[valley_idx], pch = 24, col = \"red\",  bg = \"red\",  cex = 1.2) # 谷 ▲\n\n# ==========================================\n# 日付ラベル（特大＆太字）\n# ==========================================\n# ① HMAの山（青・特大）\nif (length(peak_idx) > 0 ) {\n  text(df_recent$date[peak_idx], hma_recent[peak_idx], \n       labels = format(df_recent$date[peak_idx], \"%m/%d\"), \n       pos = 1, offset = 0.8, cex = 1.2, col = \"blue\", font = 2)\n}\n\n# ② HMAの谷（赤・特大）\nif (length(valley_idx) > 0 ) {\n  text(df_recent$date[valley_idx], hma_recent[valley_idx], \n       labels = format(df_recent$date[valley_idx], \"%m/%d\"), \n       pos = 3, offset = 0.8, cex = 1.2, col = \"red\", font = 2)\n}\n\n# ③ ヒストグラムの山（青・通常マーカー＆ラベル）\nif (length(hist_peak_idx) > 0 ) {\n  points(df_recent$date[hist_peak_idx], df_recent$hist[hist_peak_idx], pch = 6, col = \"blue\", cex = 1.0)\n  text(df_recent$date[hist_peak_idx], df_recent$hist[hist_peak_idx], \n       labels = format(df_recent$date[hist_peak_idx], \"%m/%d\"), \n       pos = 1, offset = 0.5, cex = 0.9, col = \"blue\", font = 2)\n}\n\n# ④ ヒストグラムの谷（赤・通常マーカー＆ラベル）\nif (length(hist_valley_idx) > 0 ) {\n  points(df_recent$date[hist_valley_idx], df_recent$hist[hist_valley_idx], pch = 2, col = \"red\", cex = 1.0)\n  text(df_recent$date[hist_valley_idx], df_recent$hist[hist_valley_idx], \n       labels = format(df_recent$date[hist_valley_idx], \"%m/%d\"), \n       pos = 3, offset = 0.5, cex = 0.9, col = \"red\", font = 2)\n}\n\n# 背景のグリッド・基準線を描画\nadd_month_lines(df_recent$date)\nabline(h = 0, col = \"darkgoldenrod\", lty = 1)\n\n# ==========================================\n# 【改善】ラインとマークの説明（凡例）を大きく・白背景で表示\n# ==========================================\nlegend(\n  \"topleft\", \n  legend = c(\n    \"MACD Histogram (実値)\", \n    paste0(\"HMA (\", HMA_N, \") 平滑化ライン\"), \n    \"山（HMAトレンド転換）\", \n    \"谷（HMAトレンド転換）\", \n    \"山（実値ピーク）\", \n    \"谷（実値ボトム）\"\n  ), \n  col = c(\"black\", \"red\", \"blue\", \"red\", \"blue\", \"red\"), \n  lty = c(1, 1, NA, NA, NA, NA), \n  lwd = c(1, 2, NA, NA, NA, NA), \n  pch = c(NA, NA, 25, 24, 6, 2), \n  pt.bg = c(NA, NA, \"blue\", \"red\", NA, NA),\n  pt.cex = 1.2, \n  cex = 1.0,           # 文字を大きく\n  bg = \"white\",        # 背景を白にしてグラフ線と重なっても見やすく\n  box.col = \"gray\", \n  inset = 0.02\n)\n\n# （ここより上には legend(...) のコードがあります）\n\n# ==========================================\n# 【新機能】ヒストグラムの「最新の山・谷」の日付をテキスト表示\n# ==========================================\ncat(\"\\n=========================================\\n\")\ncat(\" 📊 MACDヒストグラム（実値）直近のサイン情報\\n\")\ncat(\"=========================================\\n\")\n\n# 直近の山（ピーク）\nif (length(hist_peak_idx) > 0) {\n  latest_peak_date <- max(df_recent$date[hist_peak_idx])\n  latest_peak_val  <- df_recent$hist[df_recent$date == latest_peak_date]\n  cat(paste0(\"  ▲ 最新の山（天井）: \", format(latest_peak_date, \"%Y年%m月%d日\"), \" (値: \", round(latest_peak_val, 3), \")\\n\"))\n} else {\n  cat(\"  ▲ 最新の山（天井）: 検出なし\\n\")\n}\n\n# 直近の谷（ボトム）\nif (length(hist_valley_idx) > 0) {\n  latest_valley_date <- max(df_recent$date[hist_valley_idx])\n  latest_valley_val  <- df_recent$hist[df_recent$date == latest_valley_date]\n  cat(paste0(\"  ▼ 最新の谷（底）  : \", format(latest_valley_date, \"%Y年%m月%d日\"), \" (値: \", round(latest_valley_val, 3), \")\\n\"))\n} else {\n  cat(\"  ▼ 最新の谷（底）  : 検出なし\\n\")\n}\ncat(\"=========================================\\n\")\n\n\n\n","metadata":{"trusted":true},"outputs":[],"execution_count":null}]}